// Verify QR HMAC Signature and Expiration
const inputItem = $input.first().json || {};
const headers = inputItem.headers || {};
const body = inputItem.body || (inputItem.headers ? {} : inputItem);
const secret = headers['x-webhook-secret'] || headers['X-Webhook-Secret'] || headers['x-medconnect-secret'] || body['x-webhook-secret'] || 'medconnect-n8n-secret-key';
const EXPECTED_SECRET = 'medconnect-n8n-secret-key';

if (secret !== EXPECTED_SECRET) {
  return [{
    json: {
      success: false,
      statusCode: 401,
      error_code: 'UNAUTHORIZED',
      message: 'Invalid webhook secret',
      isValid: false
    }
  }];
}

let qrPayload = body.qr_data || body.qrData || body;
if (typeof qrPayload === 'string') {
  try { qrPayload = JSON.parse(qrPayload); } catch (e) {}
}

const appointmentId = qrPayload.appointment_id || body.appointment_id || body.appointmentId || '';
const token = qrPayload.token || body.token || '';
const issuedAt = qrPayload.issued_at || body.issued_at || new Date().toISOString();
const exp = qrPayload.exp || body.exp;

const isNotExpired = !exp || new Date(exp) > new Date();
const isValid = Boolean(appointmentId && isNotExpired);

return [{
  json: {
    ...body,
    appointment_id: appointmentId,
    token: token,
    issued_at: issuedAt,
    exp: exp,
    isValid: isValid,
    statusCode: isValid ? 200 : 400,
    error_code: isValid ? null : 'INVALID_OR_EXPIRED_QR'
  }
}];
